"""Fitness Scorer — Brier-based composite scoring and evaluation for mutations."""

from statistics import mean
from typing import Optional

from .registry import EvolutionRegistry
from .schemas import EvalResult

BRIER_WEIGHT = 0.6
YIELD_WEIGHT = 0.25
PARSE_WEIGHT = 0.15
MIN_CASES = 5
PROMOTION_THRESHOLD = 1.15
ROLLBACK_THRESHOLD = 0.20
ROLLBACK_WINDOW = 3


class FitnessScorer:
    def __init__(self, registry: EvolutionRegistry):
        self.registry = registry

    def compute_fitness(self, variant_id: int) -> Optional[float]:
        """Compute composite fitness from all fitness_log entries for this variant."""
        entries = self.registry.get_fitness_entries(variant_id)
        if not entries:
            return None

        brier_scores = [e.brier_score for e in entries if e.brier_score is not None]
        yields = [e.fact_yield for e in entries]
        parses = [e.parse_success for e in entries]

        if not yields:
            return None

        brier_component = (1.0 - mean(brier_scores)) if brier_scores else 0.5
        yield_component = min(mean(yields) / 3.0, 1.0)  # normalize: 3 facts = max
        parse_component = mean(parses)

        return (
            brier_component * BRIER_WEIGHT
            + yield_component * YIELD_WEIGHT
            + parse_component * PARSE_WEIGHT
        )

    def evaluate(self, mutation_id: int) -> EvalResult:
        """Evaluate mutation: PENDING, PROMOTE, or KILL."""
        variants = self.registry.get_variants(mutation_id)
        if not variants:
            return EvalResult(decision="KILL", reason="no variants")

        original = next((v for v in variants if v.variant_index == 0), None)
        if not original:
            return EvalResult(decision="KILL", reason="no original variant")

        if original.cases_tested < MIN_CASES:
            return EvalResult(
                decision="PENDING",
                reason=f"insufficient cases ({original.cases_tested}/{MIN_CASES})",
            )

        scores: dict[int, float] = {}
        for v in variants:
            score = self.compute_fitness(v.id)
            if score is not None:
                scores[v.id] = score

        original_score = scores.get(original.id)
        if original_score is None or original_score == 0.0:
            return EvalResult(decision="PENDING", reason="original not scored yet")

        best_id = None
        best_score = 0.0
        for vid, score in scores.items():
            if vid != original.id and score > best_score:
                best_id = vid
                best_score = score

        if best_id and best_score >= original_score * PROMOTION_THRESHOLD:
            improvement = (best_score - original_score) / original_score
            return EvalResult(
                decision="PROMOTE",
                winner_id=best_id,
                improvement_pct=round(improvement, 4),
                reason=f"variant beats original by {improvement:.1%}",
            )

        return EvalResult(
            decision="KILL",
            reason=f"best={best_score:.3f} < threshold={original_score * PROMOTION_THRESHOLD:.3f}",
        )

    def check_regression(self, mutation_id: int) -> bool:
        """Post-promotion regression check. Returns True if rollback needed."""
        variants = self.registry.get_variants(mutation_id)
        winner = next((v for v in variants if v.is_winner), None)
        original = next((v for v in variants if v.variant_index == 0), None)

        if not winner or not original:
            return False

        winner_entries = self.registry.get_fitness_entries(winner.id)
        if len(winner_entries) < ROLLBACK_WINDOW:
            return False

        recent = winner_entries[-ROLLBACK_WINDOW:]
        recent_yields = [e.fact_yield for e in recent]
        recent_parses = [e.parse_success for e in recent]

        all_entries = self.registry.get_fitness_entries(winner.id)
        pre_promo = all_entries[:-ROLLBACK_WINDOW] if len(all_entries) > ROLLBACK_WINDOW else []

        if not pre_promo:
            return False

        pre_yield = mean([e.fact_yield for e in pre_promo])
        post_yield = mean(recent_yields)

        if pre_yield > 0 and (pre_yield - post_yield) / pre_yield > ROLLBACK_THRESHOLD:
            return True

        pre_parse = mean([e.parse_success for e in pre_promo])
        post_parse = mean(recent_parses)

        if pre_parse > 0 and (pre_parse - post_parse) / pre_parse > ROLLBACK_THRESHOLD:
            return True

        return False

"""Evolution Registry — SQLite persistence for mutations, variants, and fitness tracking."""

import sqlite3
from datetime import datetime, timezone
from pathlib import Path
from typing import Optional

from .schemas import Mutation, Variant, FitnessEntry

ROOT = Path(__file__).resolve().parents[4]
DEFAULT_DB = ROOT / "data" / "evolution" / "evolution-registry.db"

SCHEMA_VERSION = 1


class EvolutionRegistry:
    def __init__(self, db_path: Optional[Path] = None):
        self.db_path = db_path or DEFAULT_DB
        self.db_path.parent.mkdir(parents=True, exist_ok=True)
        self._ensure_tables()

    def _conn(self) -> sqlite3.Connection:
        conn = sqlite3.connect(str(self.db_path))
        conn.execute("PRAGMA journal_mode=WAL")
        conn.execute("PRAGMA foreign_keys=ON")
        return conn

    def _ensure_tables(self):
        with self._conn() as conn:
            conn.executescript("""
                CREATE TABLE IF NOT EXISTS schema_meta (
                    key TEXT PRIMARY KEY,
                    value TEXT NOT NULL
                );

                CREATE TABLE IF NOT EXISTS mutations (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    created_at TEXT NOT NULL,
                    component TEXT NOT NULL,
                    target_path TEXT NOT NULL,
                    parent_id INTEGER REFERENCES mutations(id),
                    variant_count INTEGER DEFAULT 0,
                    status TEXT DEFAULT 'testing',
                    fitness_before REAL,
                    fitness_after REAL,
                    improvement_pct REAL,
                    promoted_at TEXT,
                    killed_at TEXT
                );

                CREATE TABLE IF NOT EXISTS variants (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    mutation_id INTEGER NOT NULL REFERENCES mutations(id),
                    variant_index INTEGER NOT NULL,
                    content TEXT NOT NULL,
                    fitness_score REAL,
                    cases_tested INTEGER DEFAULT 0,
                    is_winner INTEGER DEFAULT 0
                );

                CREATE TABLE IF NOT EXISTS fitness_log (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    variant_id INTEGER NOT NULL REFERENCES variants(id),
                    case_id TEXT NOT NULL,
                    brier_score REAL,
                    fact_yield REAL NOT NULL,
                    parse_success REAL NOT NULL,
                    timestamp TEXT NOT NULL
                );

                CREATE INDEX IF NOT EXISTS idx_mutations_component
                    ON mutations(component);
                CREATE INDEX IF NOT EXISTS idx_mutations_status
                    ON mutations(status);
                CREATE INDEX IF NOT EXISTS idx_variants_mutation
                    ON variants(mutation_id);
                CREATE INDEX IF NOT EXISTS idx_fitness_variant
                    ON fitness_log(variant_id);
                CREATE INDEX IF NOT EXISTS idx_fitness_case
                    ON fitness_log(case_id);
            """)
            conn.execute(
                "INSERT OR IGNORE INTO schema_meta (key, value) VALUES (?, ?)",
                ("version", str(SCHEMA_VERSION))
            )

    def _now(self) -> str:
        return datetime.now(timezone.utc).isoformat()

    # --- Mutations ---

    def create_mutation(
        self, component: str, target_path: str, parent_id: Optional[int] = None
    ) -> Mutation:
        now = self._now()
        with self._conn() as conn:
            cursor = conn.execute(
                "INSERT INTO mutations (created_at, component, target_path, parent_id, status) "
                "VALUES (?, ?, ?, ?, 'testing')",
                (now, component, target_path, parent_id),
            )
            mid = cursor.lastrowid
        return Mutation(
            id=mid, created_at=now, component=component,
            target_path=target_path, parent_id=parent_id,
            variant_count=0, status="testing",
            fitness_before=None, fitness_after=None, improvement_pct=None,
        )

    def get_mutation(self, mutation_id: int) -> Optional[Mutation]:
        with self._conn() as conn:
            row = conn.execute(
                "SELECT * FROM mutations WHERE id=?", (mutation_id,)
            ).fetchone()
        if not row:
            return None
        return self._row_to_mutation(row)

    def get_active_mutations(self, component: Optional[str] = None) -> list[Mutation]:
        with self._conn() as conn:
            if component:
                rows = conn.execute(
                    "SELECT * FROM mutations WHERE status='testing' AND component=?",
                    (component,),
                ).fetchall()
            else:
                rows = conn.execute(
                    "SELECT * FROM mutations WHERE status='testing'"
                ).fetchall()
        return [self._row_to_mutation(r) for r in rows]

    def get_recently_promoted(self, days: int = 30) -> list[Mutation]:
        from datetime import timedelta
        cutoff = (datetime.now(timezone.utc) - timedelta(days=days)).isoformat()
        with self._conn() as conn:
            rows = conn.execute(
                "SELECT * FROM mutations WHERE status='promoted' AND promoted_at >= ? "
                "ORDER BY promoted_at DESC LIMIT 20",
                (cutoff,),
            ).fetchall()
        return [self._row_to_mutation(r) for r in rows]

    def get_lineage(self, mutation_id: int, depth: int = 10) -> list[Mutation]:
        chain = []
        current_id = mutation_id
        for _ in range(depth):
            m = self.get_mutation(current_id)
            if not m:
                break
            chain.append(m)
            if not m.parent_id:
                break
            current_id = m.parent_id
        return chain

    # --- Variants ---

    def add_variant(self, mutation_id: int, index: int, content: str) -> Variant:
        with self._conn() as conn:
            cursor = conn.execute(
                "INSERT INTO variants (mutation_id, variant_index, content) VALUES (?, ?, ?)",
                (mutation_id, index, content),
            )
            vid = cursor.lastrowid
            conn.execute(
                "UPDATE mutations SET variant_count = variant_count + 1 WHERE id=?",
                (mutation_id,),
            )
        return Variant(
            id=vid, mutation_id=mutation_id, variant_index=index,
            content=content, fitness_score=None, cases_tested=0, is_winner=False,
        )

    def get_variants(self, mutation_id: int) -> list[Variant]:
        with self._conn() as conn:
            rows = conn.execute(
                "SELECT * FROM variants WHERE mutation_id=? ORDER BY variant_index",
                (mutation_id,),
            ).fetchall()
        return [self._row_to_variant(r) for r in rows]

    def get_variant(self, variant_id: int) -> Optional[Variant]:
        with self._conn() as conn:
            row = conn.execute(
                "SELECT * FROM variants WHERE id=?", (variant_id,)
            ).fetchone()
        if not row:
            return None
        return self._row_to_variant(row)

    def get_variant_by_index(self, mutation_id: int, index: int) -> Optional[Variant]:
        with self._conn() as conn:
            row = conn.execute(
                "SELECT * FROM variants WHERE mutation_id=? AND variant_index=?",
                (mutation_id, index),
            ).fetchone()
        if not row:
            return None
        return self._row_to_variant(row)

    # --- Fitness ---

    def log_fitness(
        self, variant_id: int, case_id: str,
        brier: Optional[float], fact_yield: float, parse_success: float
    ) -> FitnessEntry:
        now = self._now()
        with self._conn() as conn:
            cursor = conn.execute(
                "INSERT INTO fitness_log (variant_id, case_id, brier_score, fact_yield, parse_success, timestamp) "
                "VALUES (?, ?, ?, ?, ?, ?)",
                (variant_id, case_id, brier, fact_yield, parse_success, now),
            )
            fid = cursor.lastrowid
            conn.execute(
                "UPDATE variants SET cases_tested = cases_tested + 1 WHERE id=?",
                (variant_id,),
            )
        return FitnessEntry(
            id=fid, variant_id=variant_id, case_id=case_id,
            brier_score=brier, fact_yield=fact_yield,
            parse_success=parse_success, timestamp=now,
        )

    def get_fitness_entries(self, variant_id: int) -> list[FitnessEntry]:
        with self._conn() as conn:
            rows = conn.execute(
                "SELECT * FROM fitness_log WHERE variant_id=? ORDER BY timestamp",
                (variant_id,),
            ).fetchall()
        return [self._row_to_fitness(r) for r in rows]

    def update_brier_for_case(self, case_id: str, brier_score: float):
        with self._conn() as conn:
            conn.execute(
                "UPDATE fitness_log SET brier_score=? WHERE case_id=? AND brier_score IS NULL",
                (brier_score, case_id),
            )

    # --- Status transitions ---

    def promote_variant(self, variant_id: int):
        now = self._now()
        with self._conn() as conn:
            row = conn.execute(
                "SELECT mutation_id, fitness_score FROM variants WHERE id=?", (variant_id,)
            ).fetchone()
            if not row:
                return
            mutation_id, fitness = row
            conn.execute(
                "UPDATE variants SET is_winner=1 WHERE id=?", (variant_id,)
            )
            conn.execute(
                "UPDATE mutations SET status='promoted', promoted_at=?, fitness_after=? WHERE id=?",
                (now, fitness, mutation_id),
            )

    def kill_mutation(self, mutation_id: int):
        now = self._now()
        with self._conn() as conn:
            conn.execute(
                "UPDATE mutations SET status='killed', killed_at=? WHERE id=?",
                (now, mutation_id),
            )

    def rollback_mutation(self, mutation_id: int):
        now = self._now()
        with self._conn() as conn:
            conn.execute(
                "UPDATE mutations SET status='rolled_back', killed_at=? WHERE id=?",
                (now, mutation_id),
            )
            conn.execute(
                "UPDATE variants SET is_winner=0 WHERE mutation_id=?", (mutation_id,)
            )

    # --- Row mappers ---

    def _row_to_mutation(self, row: tuple) -> Mutation:
        return Mutation(
            id=row[0], created_at=row[1], component=row[2],
            target_path=row[3], parent_id=row[4], variant_count=row[5],
            status=row[6], fitness_before=row[7], fitness_after=row[8],
            improvement_pct=row[9], promoted_at=row[10], killed_at=row[11],
        )

    def _row_to_variant(self, row: tuple) -> Variant:
        return Variant(
            id=row[0], mutation_id=row[1], variant_index=row[2],
            content=row[3], fitness_score=row[4], cases_tested=row[5],
            is_winner=bool(row[6]),
        )

    def _row_to_fitness(self, row: tuple) -> FitnessEntry:
        return FitnessEntry(
            id=row[0], variant_id=row[1], case_id=row[2],
            brier_score=row[3], fact_yield=row[4], parse_success=row[5],
            timestamp=row[6],
        )

"""
fitness.py — Multi-metric fitness scoring for strategy evaluation.

Fitness = 0.5*brier_improvement + 0.2*correct_ratio + 0.2*info_gain + 0.1*diversity_bonus
"""

from __future__ import annotations

import json
import logging
from dataclasses import dataclass
from pathlib import Path
from typing import Optional

from .schema import Strategy

logger = logging.getLogger(__name__)

_REPO_ROOT = Path(__file__).resolve().parents[5]
_BRIER_PATH = _REPO_ROOT / "data" / "calibration" / "brier-scores.jsonl"


@dataclass
class FitnessScore:
    strategy_id: str
    brier_improvement_rate: float
    correct_verdict_ratio: float
    information_gain: float
    diversity_bonus: float
    total: float
    verdicts_evaluated: int
    window_start: int
    window_end: int

    def to_dict(self) -> dict:
        return {
            "strategy_id": self.strategy_id,
            "brier_improvement_rate": round(self.brier_improvement_rate, 4),
            "correct_verdict_ratio": round(self.correct_verdict_ratio, 4),
            "information_gain": round(self.information_gain, 4),
            "diversity_bonus": round(self.diversity_bonus, 4),
            "total": round(self.total, 4),
            "verdicts_evaluated": self.verdicts_evaluated,
            "window": [self.window_start, self.window_end],
        }


class StrategyFitness:
    WEIGHTS = {
        "brier_improvement_rate": 0.50,
        "correct_verdict_ratio": 0.20,
        "information_gain": 0.20,
        "diversity_bonus": 0.10,
    }

    def __init__(self, sandbox_results_path: Optional[Path] = None):
        self._sandbox_path = sandbox_results_path or (
            _REPO_ROOT / "data" / "evolution" / "sandbox-results.jsonl"
        )

    def score(
        self,
        strategy: Strategy,
        population: list[Strategy],
        window_size: int = 10,
    ) -> FitnessScore:
        """Compute fitness for a strategy over recent window."""
        sandbox_results = self._get_strategy_results(strategy.id)
        evaluated = [r for r in sandbox_results if r.get("actual_outcome")]

        n = min(window_size, len(evaluated))
        window = evaluated[-n:] if n > 0 else []

        brier_rate = self._brier_improvement_rate(strategy)
        correct_ratio = self._correct_verdict_ratio(strategy.id, window)
        info_gain = self._information_gain(strategy, window)
        diversity = self._diversity_bonus(strategy, population)

        total = (
            self.WEIGHTS["brier_improvement_rate"] * brier_rate
            + self.WEIGHTS["correct_verdict_ratio"] * correct_ratio
            + self.WEIGHTS["information_gain"] * info_gain
            + self.WEIGHTS["diversity_bonus"] * diversity
        )

        return FitnessScore(
            strategy_id=strategy.id,
            brier_improvement_rate=brier_rate,
            correct_verdict_ratio=correct_ratio,
            information_gain=info_gain,
            diversity_bonus=diversity,
            total=total,
            verdicts_evaluated=n,
            window_start=strategy.total_verdicts - n,
            window_end=strategy.total_verdicts,
        )

    def _brier_improvement_rate(self, strategy: Strategy) -> float:
        """Rate of Brier score improvement across fitness history."""
        history = strategy.fitness_history
        if len(history) < 2:
            return 0.5

        briers = [h.get("avg_brier", 0.5) for h in history if "avg_brier" in h]
        if len(briers) < 2:
            return 0.5

        improvements = 0
        for i in range(1, len(briers)):
            if briers[i] < briers[i - 1]:
                improvements += 1

        return improvements / (len(briers) - 1)

    def _correct_verdict_ratio(self, strategy_id: str, window: list[dict]) -> float:
        """Fraction of verdicts where strategy was correct."""
        if not window:
            return 0.5

        correct = 0
        for r in window:
            cf = r.get("counterfactuals", {}).get(strategy_id, {})
            verdict = cf.get("verdict", "")
            outcome = r.get("actual_outcome", "")
            if self._matches(verdict, outcome):
                correct += 1

        return correct / len(window)

    def _information_gain(self, strategy: Strategy, window: list[dict]) -> float:
        """How much new signal compared to parent strategy."""
        if not strategy.parent_id or not window:
            return 0.5

        parent_correct = 0
        child_correct = 0
        for r in window:
            cfs = r.get("counterfactuals", {})
            parent_cf = cfs.get(strategy.parent_id, {})
            child_cf = cfs.get(strategy.id, {})
            outcome = r.get("actual_outcome", "")

            if self._matches(parent_cf.get("verdict", ""), outcome):
                parent_correct += 1
            if self._matches(child_cf.get("verdict", ""), outcome):
                child_correct += 1

        if not window:
            return 0.5
        parent_rate = parent_correct / len(window)
        child_rate = child_correct / len(window)
        return max(0.0, min(1.0, 0.5 + (child_rate - parent_rate)))

    def _diversity_bonus(self, strategy: Strategy, population: list[Strategy]) -> float:
        """Reward strategies that are different from population average."""
        if not population:
            return 0.5
        distances = [strategy.jaccard_distance(s) for s in population if s.id != strategy.id]
        if not distances:
            return 0.5
        avg_distance = sum(distances) / len(distances)
        return min(1.0, avg_distance * 2)

    def _matches(self, verdict: str, outcome: str) -> bool:
        outcome_lower = outcome.lower()
        if verdict == "GO":
            return outcome_lower in ("success", "profitable", "go", "positive")
        elif verdict == "NO-GO":
            return outcome_lower in ("failure", "loss", "no-go", "negative", "killed")
        return False

    def _get_strategy_results(self, strategy_id: str) -> list[dict]:
        if not self._sandbox_path.exists():
            return []
        results = []
        for line in self._sandbox_path.read_text(encoding="utf-8").strip().split("\n"):
            if not line.strip():
                continue
            try:
                r = json.loads(line)
                if strategy_id in r.get("counterfactuals", {}):
                    results.append(r)
            except json.JSONDecodeError:
                continue
        return results

"""
meta_meta.py — Meta-meta loop: evolves the evolution strategy itself.

Detects stagnation in strategy evolution and mutates selection/variation parameters.
Extremely conservative: monthly cadence, 10% max adjustment, auto-revert.
"""

from __future__ import annotations

import json
import logging
from dataclasses import dataclass, field
from datetime import datetime, timezone, timedelta
from pathlib import Path
from typing import Optional

from .schema import Strategy

logger = logging.getLogger(__name__)

_REPO_ROOT = Path(__file__).resolve().parents[5]
_META_META_HISTORY = _REPO_ROOT / "data" / "evolution" / "meta-meta-history.jsonl"
_META_META_CONFIG = _REPO_ROOT / "data" / "evolution" / "meta-meta-config.json"

MIN_CYCLES_BEFORE_FIRST_RUN = 6
MAX_PARAM_ADJUSTMENT = 0.10
MIN_INTERVAL_DAYS = 30


@dataclass
class StagnationSignal:
    signal_type: str  # fitness_plateau | diversity_collapse | kill_breed_loop | outcome_surprise
    severity: float  # 0-1
    detail: str

    def to_dict(self) -> dict:
        return {"type": self.signal_type, "severity": self.severity, "detail": self.detail}


@dataclass
class MetaMetaResult:
    stagnation_detected: bool
    signal: Optional[StagnationSignal] = None
    mutation_applied: Optional[str] = None
    old_value: Optional[float] = None
    new_value: Optional[float] = None
    blocked_reason: Optional[str] = None

    def to_dict(self) -> dict:
        return {
            "timestamp": datetime.now(timezone.utc).isoformat(),
            "stagnation_detected": self.stagnation_detected,
            "signal": self.signal.to_dict() if self.signal else None,
            "mutation_applied": self.mutation_applied,
            "old_value": self.old_value,
            "new_value": self.new_value,
            "blocked_reason": self.blocked_reason,
        }


class StagnationDetector:
    def detect(
        self,
        population: list[Strategy],
        selection_history: list[dict],
    ) -> Optional[StagnationSignal]:
        """Check all stagnation signals, return first triggered."""
        signal = self._check_fitness_plateau(population)
        if signal:
            return signal

        signal = self._check_diversity_collapse(population)
        if signal:
            return signal

        signal = self._check_kill_breed_loop(selection_history)
        if signal:
            return signal

        return None

    def _check_fitness_plateau(self, population: list[Strategy]) -> Optional[StagnationSignal]:
        """Best strategy fitness unchanged for 3 consecutive windows."""
        for strategy in population:
            if strategy.status != "active":
                continue
            history = strategy.fitness_history
            if len(history) < 3:
                return None
            last_3 = [h.get("total", 0) for h in history[-3:]]
            if max(last_3) - min(last_3) < 0.01:
                return StagnationSignal(
                    signal_type="fitness_plateau",
                    severity=0.7,
                    detail=f"Active strategy fitness flat at ~{last_3[-1]:.3f} for 3 windows",
                )
        return None

    def _check_diversity_collapse(self, population: list[Strategy]) -> Optional[StagnationSignal]:
        """Population too similar (avg Jaccard similarity > 0.8)."""
        if len(population) < 2:
            return None
        total_sim = 0.0
        pairs = 0
        for i, a in enumerate(population):
            for b in population[i + 1:]:
                total_sim += (1.0 - a.jaccard_distance(b))
                pairs += 1
        if pairs == 0:
            return None
        avg_sim = total_sim / pairs
        if avg_sim > 0.8:
            return StagnationSignal(
                signal_type="diversity_collapse",
                severity=0.8,
                detail=f"Population avg similarity {avg_sim:.2f} > 0.8 threshold",
            )
        return None

    def _check_kill_breed_loop(self, selection_history: list[dict]) -> Optional[StagnationSignal]:
        """Same lineage killed 3+ times."""
        kill_counts: dict[str, int] = {}
        for entry in selection_history[-20:]:
            if entry.get("killed"):
                kid = entry["killed"]
                kill_counts[kid] = kill_counts.get(kid, 0) + 1

        for kid, count in kill_counts.items():
            if count >= 3:
                return StagnationSignal(
                    signal_type="kill_breed_loop",
                    severity=0.6,
                    detail=f"Strategy {kid[:8]} lineage killed {count} times",
                )
        return None


class MetaMetaController:
    def __init__(self):
        self._history_path = _META_META_HISTORY
        self._config_path = _META_META_CONFIG
        self._history_path.parent.mkdir(parents=True, exist_ok=True)
        self.detector = StagnationDetector()

    def run(
        self,
        population: list[Strategy],
        selection_history: list[dict],
    ) -> MetaMetaResult:
        """Run meta-meta check. Apply mutation if stagnation detected."""
        if not self._can_run():
            return MetaMetaResult(
                stagnation_detected=False,
                blocked_reason="Rate limited (min 30 days between runs)",
            )

        signal = self.detector.detect(population, selection_history)
        if signal is None:
            return MetaMetaResult(stagnation_detected=False)

        config = self._load_config()
        mutation = self._propose_mutation(signal, config)

        if mutation:
            result = MetaMetaResult(
                stagnation_detected=True,
                signal=signal,
                mutation_applied=mutation["param"],
                old_value=mutation["old"],
                new_value=mutation["new"],
            )
            config[mutation["param"]] = mutation["new"]
            self._save_config(config)
            self._persist_result(result)
            logger.info("Meta-meta applied: %s %s→%s", mutation["param"], mutation["old"], mutation["new"])
            return result

        return MetaMetaResult(stagnation_detected=True, signal=signal, blocked_reason="No viable mutation")

    def check_regression_and_revert(self, recent_scores: list[float]) -> bool:
        """Auto-revert if last meta-meta made things worse."""
        history = self._load_history()
        if not history:
            return False

        last = history[-1]
        if not last.get("mutation_applied"):
            return False

        if len(recent_scores) < 2:
            return False

        if all(s < recent_scores[0] for s in recent_scores[1:]):
            config = self._load_config()
            param = last["mutation_applied"]
            old_val = last.get("old_value")
            if old_val is not None and param in config:
                config[param] = old_val
                self._save_config(config)
                logger.warning("Meta-meta REVERTED: %s back to %s", param, old_val)
                return True
        return False

    def _can_run(self) -> bool:
        history = self._load_history()
        if not history:
            return True
        last_ts = history[-1].get("timestamp", "")
        if not last_ts:
            return True
        try:
            last_dt = datetime.fromisoformat(last_ts)
            return (datetime.now(timezone.utc) - last_dt) > timedelta(days=MIN_INTERVAL_DAYS)
        except (ValueError, TypeError):
            return True

    def _propose_mutation(self, signal: StagnationSignal, config: dict) -> Optional[dict]:
        """Propose a parameter adjustment based on stagnation signal."""
        if signal.signal_type == "fitness_plateau":
            param = "mutation_diversity_pressure"
            old = config.get(param, 0.5)
            new = min(1.0, old + MAX_PARAM_ADJUSTMENT)
            return {"param": param, "old": old, "new": round(new, 2)}

        elif signal.signal_type == "diversity_collapse":
            param = "wild_injection_interval"
            old = config.get(param, 3)
            new = max(1, old - 1)
            if new == old:
                return None
            return {"param": param, "old": old, "new": new}

        elif signal.signal_type == "kill_breed_loop":
            param = "grace_period_verdicts"
            old = config.get(param, 5)
            new = min(10, old + 1)
            return {"param": param, "old": old, "new": new}

        return None

    def _load_config(self) -> dict:
        if self._config_path.exists():
            try:
                return json.loads(self._config_path.read_text(encoding="utf-8"))
            except (json.JSONDecodeError, OSError):
                pass
        return {
            "mutation_diversity_pressure": 0.5,
            "wild_injection_interval": 3,
            "grace_period_verdicts": 5,
            "window_size": 10,
            "max_population": 5,
        }

    def _save_config(self, config: dict):
        self._config_path.parent.mkdir(parents=True, exist_ok=True)
        self._config_path.write_text(
            json.dumps(config, indent=2, ensure_ascii=False), encoding="utf-8"
        )

    def _load_history(self) -> list[dict]:
        if not self._history_path.exists():
            return []
        results = []
        for line in self._history_path.read_text(encoding="utf-8").strip().split("\n"):
            if line.strip():
                try:
                    results.append(json.loads(line))
                except json.JSONDecodeError:
                    continue
        return results

    def _persist_result(self, result: MetaMetaResult):
        with open(self._history_path, "a", encoding="utf-8") as f:
            f.write(json.dumps(result.to_dict(), ensure_ascii=False) + "\n")

