# ------------------------------------------------------------------
# Revenue event logging (deal pipeline → evolution fitness)
# ------------------------------------------------------------------

def log_revenue_event(self, event: RevenueEvent) -> None:
    """
    Append a revenue event to the revenue-outcomes JSONL file.

    These events feed the evolution fitness function with real $ signals.
    """
    revenue_file = self._data_dir.parent / "calibration" / "revenue-outcomes.jsonl"
    revenue_file.parent.mkdir(parents=True, exist_ok=True)
    with open(revenue_file, "a", encoding="utf-8") as f:
        f.write(event.to_json_line() + "\n")
    logger.info(
        "Revenue event: %s %s→%s reward=%.2f amount=%s",
        event.case_id, event.stage_from, event.stage_to,
        event.reward_signal, event.revenue_amount,
    )

def get_revenue_events(self, case_id: Optional[str] = None) -> list[RevenueEvent]:
    """Load revenue events, optionally filtered by case_id."""
    revenue_file = self._data_dir.parent / "calibration" / "revenue-outcomes.jsonl"
    if not revenue_file.exists():
        return []
    events: list[RevenueEvent] = []
    for line in revenue_file.read_text(encoding="utf-8").strip().split("\n"):
        if not line.strip():
            continue
        try:
            data = json.loads(line)
            evt = RevenueEvent.from_dict(data)
            if case_id is None or evt.case_id == case_id:
                events.append(evt)
        except (json.JSONDecodeError, KeyError, ValueError):
            continue
    return events

def get_cumulative_reward(self, case_id: str) -> float:
    """Get max reward signal for a case (0.0–1.0)."""
    events = self.get_revenue_events(case_id)
    if not events:
        return 0.0
    return max(e.reward_signal for e in events)

def get_days_to_first_action(self, case_id: str) -> Optional[int]:
    """Get days_since_verdict for the first event of this case."""
    events = self.get_revenue_events(case_id)
    if not events:
        return None
    return min(e.days_since_verdict for e in events)

# ------------------------------------------------------------------
# Internal helpers (used by resolver.py)
# ------------------------------------------------------------------

def _update_prediction(self, pred: Prediction) -> None:
    """Persist an updated Prediction (called by resolver)."""
    self._store.update_prediction(pred)

def _update_decision(self, dec: Decision) -> None:
    """Persist an updated Decision (called by resolver)."""
    self._store.update_decision(dec)

