def _complexity_penalty(self, strategy: Strategy) -> float:
    """Lower = simpler = better. Returns 0.0-1.0 penalty magnitude.
    Max 10% impact on total fitness (COMPLEXITY_PENALTY_CAP).
    """
    agent_count = len(getattr(strategy, "wave1_agents", []) or []) + \
                  len(getattr(strategy, "wave2_agents", []) or [])
    agent_penalty = min(agent_count / 20.0, 1.0)

    templates = getattr(strategy, "templates", {}) or {}
    template_chars = sum(len(str(t)) for t in templates.values())
    length_penalty = min(template_chars / 10000.0, 1.0)

    return agent_penalty * 0.6 + length_penalty * 0.4

