"""
fitness.py — Revenue-grounded multi-metric fitness scoring for strategy evaluation.

Revenue mode:  0.3*brier + 0.3*revenue_attribution + 0.2*correct_ratio + 0.1*info_gain + 0.1*diversity
Fallback mode: 0.5*brier + 0.2*correct_ratio + 0.2*info_gain + 0.1*diversity
"""

from __future__ import annotations

import json
import logging
from dataclasses import dataclass
from pathlib import Path
from typing import Optional

from .schema import Strategy

logger = logging.getLogger(__name__)

_REPO_ROOT = Path(__file__).resolve().parents[5]
_BRIER_PATH = _REPO_ROOT / "data" / "calibration" / "brier-scores.jsonl"
_REVENUE_PATH = _REPO_ROOT / "data" / "calibration" / "revenue-outcomes.jsonl"

MIN_REVENUE_EVENTS = 3


@dataclass
class FitnessScore:
    strategy_id: str
    brier_improvement_rate: float
    correct_verdict_ratio: float
    information_gain: float
    diversity_bonus: float
    revenue_attribution: float
    total: float
    verdicts_evaluated: int
    window_start: int
    window_end: int
    revenue_mode: bool

    def to_dict(self) -> dict:
        return {
            "strategy_id": self.strategy_id,
            "brier_improvement_rate": round(self.brier_improvement_rate, 4),
            "correct_verdict_ratio": round(self.correct_verdict_ratio, 4),
            "information_gain": round(self.information_gain, 4),
            "diversity_bonus": round(self.diversity_bonus, 4),
            "revenue_attribution": round(self.revenue_attribution, 4),
            "total": round(self.total, 4),
            "verdicts_evaluated": self.verdicts_evaluated,
            "window": [self.window_start, self.window_end],
            "revenue_mode": self.revenue_mode,
        }


class StrategyFitness:
    WEIGHTS_REVENUE = {
        "brier_improvement_rate": 0.30,
        "revenue_attribution": 0.30,
        "correct_verdict_ratio": 0.20,
        "information_gain": 0.10,
        "diversity_bonus": 0.10,
    }
    WEIGHTS_FALLBACK = {
        "brier_improvement_rate": 0.50,
        "correct_verdict_ratio": 0.20,
        "information_gain": 0.20,
        "diversity_bonus": 0.10,
    }

    def __init__(self, sandbox_results_path: Optional[Path] = None):
