                continue
        self._revenue_cache = events
        return events

    def _revenue_attribution(self, strategy: Strategy) -> float:
        """How much revenue signal is attributed to verdicts made under this strategy."""
        events = self._load_revenue_events()
        if not events:
            return 0.0
        sandbox_results = self._get_strategy_results(strategy.id)
        strategy_case_ids = {r.get("case_id", "") for r in sandbox_results}
        matched = [e for e in events if e.get("case_id") in strategy_case_ids]
        if not matched:
            return 0.0
        return min(1.0, max(e.get("reward_signal", 0.0) for e in matched))

    def score(
        self,
        strategy: Strategy,
        population: list[Strategy],
        window_size: int = 10,
    ) -> FitnessScore:
        """Compute fitness for a strategy over recent window."""
        sandbox_results = self._get_strategy_results(strategy.id)
        evaluated = [r for r in sandbox_results if r.get("actual_outcome")]

        n = min(window_size, len(evaluated))
        window = evaluated[-n:] if n > 0 else []

        brier_rate = self._brier_improvement_rate(strategy)
        correct_ratio = self._correct_verdict_ratio(strategy.id, window)
        info_gain = self._information_gain(strategy, window)
        diversity = self._diversity_bonus(strategy, population)
        revenue = self._revenue_attribution(strategy)
        revenue_mode = self._is_revenue_mode()

        if revenue_mode:
            weights = self.WEIGHTS_REVENUE
            total = (
                weights["brier_improvement_rate"] * brier_rate
                + weights["revenue_attribution"] * revenue
                + weights["correct_verdict_ratio"] * correct_ratio
                + weights["information_gain"] * info_gain
                + weights["diversity_bonus"] * diversity
            )
        else:
            weights = self.WEIGHTS_FALLBACK
            total = (
                weights["brier_improvement_rate"] * brier_rate
                + weights["correct_verdict_ratio"] * correct_ratio
                + weights["information_gain"] * info_gain
                + weights["diversity_bonus"] * diversity
            )

